impl Solution {
    pub fn max_students(seats: Vec<Vec<char>>) -> i32 {
        let m = seats.len();
        let n = seats[0].len();

        // Precompute valid seat masks for each row
        // A bit in the mask is 1 if the seat is available ('.'), else 0
        let mut valid_rows = vec![0; m];
        for i in 0..m {
            let mut mask = 0;
            for j in 0..n {
                if seats[i][j] == '.' {
                    mask |= 1 << j;
                }
            }
            valid_rows[i] = mask;
        }

        // Precompute all valid seat arrangements for each row
        // A valid arrangement must be a subset of valid_rows[i]
        // and no two students sit next to each other in the same row
        let mut valid_arrangements = vec![Vec::new(); m];
        for i in 0..m {
            let limit = 1 << n;
            for state in 0..limit {
                // state must be subset of valid_rows[i]
                if (state & !valid_rows[i]) != 0 {
                    continue;
                }
                // no two adjacent students in the same row
                if (state & (state << 1)) != 0 {
                    continue;
                }
                valid_arrangements[i].push(state);
            }
        }

        // dp[row][state] = max students placed up to row with arrangement state in this row
        // state is the bitmask of students placed in current row
        let mut dp = vec![std::collections::HashMap::new(); m];

        // Initialize dp for row 0
        for &state in &valid_arrangements[0] {
            let count = state.count_ones() as i32;
            dp[0].insert(state, count);
        }

        for i in 1..m {
            for &curr in &valid_arrangements[i] {
                let curr_count = curr.count_ones() as i32;
                for (&prev, &prev_count) in dp[i - 1].iter() {
                    // Check no cheating between current row and previous row:
                    // Students cannot see upper left and upper right neighbors
                    // So no student in curr at j can have a student in prev at j-1 or j+1
                    if (curr & (prev << 1)) == 0 && (curr & (prev >> 1)) == 0 {
                        let total = prev_count + curr_count;
                        let entry = dp[i].entry(curr).or_insert(total);
                        if *entry < total {
                            *entry = total;
                        }
                    }
                }
            }
        }

        // The answer is the max value in dp[m-1]
        dp[m - 1].values().copied().max().unwrap_or(0)
    }
}

